void Write(const char* status,const std::string& error="") {std::ofstream(output)<<nlohmann::json{{"status",status},{"error",error},{"phase",phase},{"phase_frames",frames},{"render_frames",drawFrames},{"blade_rotations",rotations.size()},{"stun_frames",stunFrames},{"larva_recoil_frames",recoilFrames},{"explosion_bombs",bombCount},{"native_defeats",kills},{"adult_defeats",adultKills},{"larva_defeats",larvaKills},{"native_blade_quad",bladeQuad},{"native_blade_tips",bladeTips},{"fixture",{anchor.x,anchor.y,anchor.z}},{"checks",checks}}.dump(2);}
void Check(bool ok,const char* label){if(!ok)throw std::runtime_error(label);checks.push_back(label);SPDLOG_INFO("[Peahat QA] PASS {}",label);Write("running");}
bool Alive(const Actor* target){for(auto& list:gPlayState->actorCtx.actorLists)for(auto* a=list.head;a;a=a->next)if(a==target)return a->update!=nullptr;return false;}
void Time(){gSaveContext.dayTime=gSaveContext.skyboxTime=day?0x8000:0;gSaveContext.nightFlag=day?0:1;}
void Warp(){gSaveContext.entranceIndex=ENTR_HYRULE_FIELD_PAST_BRIDGE_SPAWN;gSaveContext.cutsceneIndex=0;gSaveContext.sceneLayer=0;gSaveContext.respawnFlag=0;gGameState->running=false;SET_NEXT_GAMESTATE(gGameState,Play_Init,PlayState);enemy=larva=nullptr;children.clear();}
void Camera(){Time();auto* p=GET_PLAYER(gPlayState);gSaveContext.health=gSaveContext.healthCapacity;p->invincibilityTimer=20;p->actor.world.pos=p->actor.prevPos=fixture;p->actor.speedXZ=0;p->actor.velocity={};p->actor.shape.rot.y=Math_Vec3f_Yaw(&fixture,&anchor);Vec3f at={anchor.x,anchor.y+90,anchor.z},eye={anchor.x+260,anchor.y+105,anchor.z+370};Play_CameraSetAtEye(gPlayState,CAM_ID_MAIN,&at,&eye);}
void Clear(){for(auto& list:gPlayState->actorCtx.actorLists)for(auto* a=list.head;a;a=a->next)if(a->category==ACTORCAT_ENEMY||a->id==ACTOR_EN_ENCOUNT1)Actor_Kill(a);enemy=larva=nullptr;children.clear();}
EnPeehat* Spawn(int type){auto p=anchor;if(type==1)p.y+=150;auto* a=Actor_Spawn(&gPlayState->actorCtx,gPlayState,ACTOR_EN_PEEHAT,p.x,p.y,p.z,0,0,0,type);Check(a&&a->update,"Original Peahat actor initializes");a->flags|=ACTOR_FLAG_DRAW_CULLING_DISABLED|ACTOR_FLAG_UPDATE_CULLING_DISABLED;return reinterpret_cast<EnPeehat*>(a);}
std::vector<EnPeehat*> Children(EnPeehat* parent){std::vector<EnPeehat*> list;for(auto* a=gPlayState->actorCtx.actorLists[ACTORCAT_ENEMY].head;a;a=a->next)if(a->update&&a->id==ACTOR_EN_PEEHAT&&a->params==1&&a->parent==&parent->actor)list.push_back(reinterpret_cast<EnPeehat*>(a));return list;}
Gfx* Model(EnPeehat* a,int limb,bool original=false){auto* dl=static_cast<StandardLimb*>(a->skelAnime.skeleton[(limb==24?3:limb)-1])->dList;if(!original){if(limb==24)ARPG_OverridePeahatRoot(gPlayState,&a->actor,&dl);else ARPG_OverridePeahatLimb(gPlayState,&a->actor,limb,&dl);}return dl;}
void Models(EnPeehat* a){Check(a->skelAnime.limbCount==24&&a->skelAnime.jointTable==a->jointTable&&a->skelAnime.morphTable==a->morphTable,"Original 24-entry rig retains embedded native animation tables");bool replaced=true,cached=true;for(int l:PeahatGeometry::Limbs){auto* m=Model(a,l);replaced&=m&&m!=Model(a,l,true);cached&=m==Model(a,l);}Check(replaced,"Original bulb, crown and all six blade limbs use the authored model");Check(cached,"Repeated draws reuse cached rigid native geometry");Check((Model(a,24)!=Model(a,24,true))==(a->actor.params<=0),"Only adults receive the independently authored exposed root");
 for(auto key:{"gEnhancements.ARPG.Enabled","gEnhancements.ARPG.RemasteredEnemies"}){CVarSetInteger(key,0);bool off=Model(a,24)==Model(a,24,true);for(int l:PeahatGeometry::Limbs)off&=Model(a,l)==Model(a,l,true);Check(off,"Disabling ARPG or remastered enemies restores the native model and root");CVarSetInteger(key,1);}
 auto eye=GET_ACTIVE_CAM(gPlayState)->eye;GET_ACTIVE_CAM(gPlayState)->eye.x+=10000;Check(Model(a,3)==Model(a,3,true)&&Model(a,24)==Model(a,24,true),"Distance fallback restores native body and weak point");GET_ACTIVE_CAM(gPlayState)->eye=eye;
 Check(Model(a,4)==nullptr,"Hidden spinning rotor joint stays hidden");
 if(a->actor.params<=0)Check(std::abs(a->actor.scale.x-.036f)<.00001&&a->colCylinder.dim.radius==50&&a->colCylinder.dim.height==160,"Adult scale and original protective cylinder remain intact");
 else Check(a->actor.scale.x==.006f&&a->actor.scale.y==.003f&&a->actor.scale.z==.006f&&a->colCylinder.dim.radius==25&&a->colCylinder.dim.height==15,"Larvae retain their flattened native scale and smaller collision cylinder");}
void Damage(int amount,int effect){enemy->colJntSph.base.acFlags|=AC_HIT;enemy->actor.colChkInfo.damage=amount;enemy->actor.colChkInfo.damageEffect=effect;EnPeehat_Adult_CollisionCheck(enemy,gPlayState);enemy->actor.colChkInfo.damageEffect=0;}
void Next(int p){phase=p;frames=0;}
void Tick(){if(phase>=98)return;try{++frames;
 if(phase==0&&frames>60&&gGameState){CVarSetInteger("gDeveloperTools.DebugSaveFileMode",2);gSaveContext.gameMode=GAMEMODE_NORMAL;gSaveContext.fileNum=0xFE;Sram_InitDebugSave();gSaveContext.fileNum=0xFF;gSaveContext.linkAge=LINK_AGE_CHILD;gARPGSave={};Time();for(auto k:{"gEnhancements.ARPG.Enabled","gEnhancements.ARPG.RemasteredEnemies"})CVarSetInteger(k,1);for(auto k:{"gEnhancements.ARPG.Affixes","gEnhancements.ARPG.Items","gEnhancements.ARPG.Skills","gEnhancements.ARPG.Enemies","gEnhancements.ARPG.Creatures","gEnhancements.ARPG.Packs","gEnhancements.ARPG.Enchanted","gEnhancements.ARPG.RegionalWorld","gOpenWindows.ARPG"})CVarSetInteger(k,0);SeedRng(0xFEA);Warp();Next(1);return;}
 if(gPlayState&&phase>=2&&phase<20)Camera();
 if(phase==1&&frames>100&&gPlayState&&GameInteractor::IsPlayerInControl()){fixture=nearPlayer=GET_PLAYER(gPlayState)->actor.world.pos;Actor* practice=nullptr;for(int i=0;i<16&&!practice;++i){GET_PLAYER(gPlayState)->actor.shape.rot.y=i*0x1000;practice=Creatures::SpawnPeahatPractice(gPlayState,0);}if(!practice){for(auto* a=gPlayState->actorCtx.actorLists[ACTORCAT_ENEMY].head;a;a=a->next)SPDLOG_INFO("[Peahat QA] Original enemy {} type {} at {},{},{}",a->id,a->params,a->world.pos.x,a->world.pos.y,a->world.pos.z);SPDLOG_INFO("[Peahat QA] Player {},{},{}",fixture.x,fixture.y,fixture.z);}Check(practice,"Hunter practice finds open ground beside the original field population");anchor=practice->world.pos;Actor_Kill(practice);Clear();Camera();enemy=Spawn(-1);Models(enemy);Next(2);return;}
 if(phase==2&&frames>25){Check(enemy->actionFunc==EnPeehat_Ground_StateGround&&enemy->actor.shape.yOffset==-1000&&!(enemy->actor.flags&ACTOR_FLAG_ATTENTION_ENABLED),"Native night rest sinks the bulb and releases targeting");if((gPlayState->gameplayFrames&15)==0)return;EnPeehat_HitWhenGrounded(enemy,gPlayState);children=Children(enemy);Check(children.size()==3,"A disturbed sleeping adult releases three native larvae");EnPeehat_Ground_SetStateGround(enemy);EnPeehat_HitWhenGrounded(enemy,gPlayState);Check(EnPeehat_CountLarvae(gPlayState,enemy)==3,"Resetting the ground state cannot bypass the living-child cap");for(auto* c:children)Actor_Kill(&c->actor);children.clear();day=true;Time();Next(3);return;}
 if(phase==3){sawRise|=enemy->actionFunc==EnPeehat_Ground_StateRise;sawHover|=enemy->actionFunc==EnPeehat_Ground_StateHover;if(enemy->actionFunc==EnPeehat_Ground_StateSeekPlayer){Check(sawRise&&sawHover&&enemy->actor.world.pos.y>enemy->actor.floorHeight+65,"Daylight runs the original takeoff, hover and pursuit transitions");flightStart=enemy->actor.world.pos;Next(4);return;}}
 if(phase==4&&frames>55){Check(Math_Vec3f_DistXZ(&flightStart,&enemy->actor.world.pos)>80&&enemy->actor.speedXZ==3&&enemy->bladeRotVel==4000,"Hunting adult advances with native pursuit speed and spinning blades");Check(bladeQuad&&bladeTips&&rotations.size()>20,"Original blade collision quad and dust-tip transforms follow native rotation");Check(enemy->colJntSph.elements[0].dim.worldSphere.radius==20,"Exposed root keeps the original damage sphere");auto c=enemy->colJntSph.elements[0].dim.worldSphere.center;Vec3f p={float(c.x),float(c.y),float(c.z)};Check(Math_Vec3f_DistXYZ(&p,&enemy->actor.focus.pos)<10,"Native targeting tracks the exposed weak root");fixture=anchor;fixture.x+=1600;Next(5);return;}
 if(phase==5){sawReturn|=enemy->actionFunc==EnPeehat_Ground_StateReturnHome;sawLanding|=enemy->actionFunc==EnPeehat_Ground_StateLanding;if(enemy->actionFunc==EnPeehat_Ground_StateGround){SPDLOG_INFO("[Peahat QA] Return {}, landing {}, home distance {}, at {},{},{}",sawReturn,sawLanding,Math_Vec3f_DistXZ(&enemy->actor.world.pos,&enemy->actor.home.pos),enemy->actor.world.pos.x,enemy->actor.world.pos.y,enemy->actor.world.pos.z);Check(sawReturn&&sawLanding&&Math_Vec3f_DistXZ(&enemy->actor.world.pos,&enemy->actor.home.pos)<10,"Leaving its hunting range returns the original adult to its home area and lands");fixture=nearPlayer;Next(6);return;}}
 if(phase==6&&enemy->actionFunc==EnPeehat_Ground_StateSeekPlayer){Check(enemy->actor.colChkInfo.health==6,"Rested adult rises again with unchanged health");enemy->colCylinder.base.acFlags|=AC_BOUNCED;Damage(2,0);Check(enemy->actor.colChkInfo.health==6&&!(enemy->colJntSph.base.acFlags&AC_HIT),"Armored body bounce protects the weak-point hit");Damage(3,15);Damage(3,6);Check(enemy->actor.colChkInfo.health==6,"Deku nuts and light/ice effect retain their native immunity");Damage(1,0);Check(enemy->actor.colChkInfo.health==5,"An exposed-root weapon hit applies native damage");Damage(0,14);Check(enemy->actionFunc==EnPeehat_StateBoomerangStunned&&enemy->bladeRotVel==0&&enemy->actor.colorFilterTimer==80,"Boomerang stops the rotor and opens the native stun window");Damage(0,14);Check(enemy->actor.colChkInfo.health==5&&enemy->actor.colorFilterTimer==80,"Repeated boomerang stun never becomes damage");Next(7);return;}
 if(phase==7&&frames>90){Check(stunFrames>=70&&enemy->actionFunc!=EnPeehat_StateBoomerangStunned,"Native stun expiry begins takeoff again");Damage(0,13);Check(enemy->actor.colChkInfo.health==0&&enemy->actionFunc==EnPeehat_Adult_StateDie&&kills==0,"Hookshot defeats the exposed root through its delayed native death");Next(8);return;}
 if(phase==8&&frames>35){Check(!Alive(reinterpret_cast<Actor*>(enemy))&&adultKills==1&&kills==1&&gARPGSave.kills==1&&bombCount==1,"Hookshot death shrinks, explodes and grants one defeat");enemy=Spawn(-1);bombs.clear();Next(9);return;}
 if(phase==9&&enemy->actionFunc==EnPeehat_Ground_StateSeekPlayer){Damage(2,12);Check(enemy->actor.colChkInfo.health==4&&enemy->actor.colorFilterTimer==100,"Fire keeps its native damage and extended burning filter");Next(10);return;}
 if(phase==10&&frames>12){Damage(4,0);Next(11);return;}
 if(phase==11&&frames>35){Check(adultKills==2&&kills==2&&bombCount==2,"Ordinary lethal root damage also produces exactly one explosive defeat");enemy=Spawn(0);Models(enemy);Next(12);return;}
 if(phase==12){if(enemy->actionFunc==EnPeehat_Flying_StateFly&&EnPeehat_CountLarvae(gPlayState,enemy)==3){Check(enemy->actor.world.pos.y>enemy->actor.floorHeight+200&&enemy->unk_2FA==3,"Brood parent ascends to its native height and releases three larvae");children=Children(enemy);day=false;Time();Next(13);return;}}
 if(phase==13||phase==14){for(auto* c:children)if(Alive(&c->actor)){c->actor.world.pos={anchor.x+200,anchor.y+220,anchor.z};c->actor.velocity={};c->actor.bgCheckFlags&=~BGCHECKFLAG_GROUND;}
  if(phase==13&&enemy->actionFunc==EnPeehat_Flying_StateGrounded){Check(Children(enemy).size()==3,"Brood parent lands at night while existing larvae remain owned");day=true;Time();Next(14);return;}
  if(phase==14&&enemy->actionFunc==EnPeehat_Flying_StateFly&&frames>70){Check(Children(enemy).size()==3&&enemy->unk_2FA==3,"Repeated day/night ascent does not duplicate an existing brood");Actor_Kill(&enemy->actor);enemy=nullptr;Next(15);return;}}
 if(phase==15&&frames>4){bool detached=children.size()==3;for(auto* c:children)detached&=Alive(&c->actor)&&!c->actor.parent&&c->actionFunc==EnPeehat_Larva_StateSeekPlayer;Check(detached,"Removing a parent detaches every larva while preserving native pursuit");for(auto* c:children)Actor_Kill(&c->actor);children.clear();larva=Spawn(1);Models(larva);Next(16);return;}
 if(phase==16&&frames>5){larva->actor.parent=&GET_PLAYER(gPlayState)->actor;EnPeehat_Larva_StateSeekPlayer(larva,gPlayState);Check(!larva->actor.parent&&larva->actor.speedXZ==5.3f,"Invalid parent references detach safely without changing larva pursuit speed");larva->colliderQuad.base.at=&GET_PLAYER(gPlayState)->actor;larva->colliderQuad.base.atFlags|=AT_HIT;EnPeehat_Larva_StateSeekPlayer(larva,gPlayState);Check(Alive(&larva->actor)&&larva->unk_2D4==40&&larva->actor.colChkInfo.health==6,"Larva contact retains its native turn-away cooldown without killing it");larva->colliderQuad.base.atFlags|=AT_HIT|AT_BOUNCED;EnPeehat_Larva_StateSeekPlayer(larva,gPlayState);Check(larva->actionFunc==EnPeehat_StateAttackRecoil&&larva->actor.speedXZ==-9&&larva->actor.colChkInfo.health==0&&!(larva->colliderQuad.base.atFlags&(AT_HIT|AT_BOUNCED)),"Shield reflection clears attack flags and starts the native lethal recoil");Next(17);return;}
 if(phase==17&&frames>25){Check(!Alive(reinterpret_cast<Actor*>(larva))&&larvaKills==1&&recoilFrames>=15,"Reflected larva completes recoil and grants one defeat");larva=Spawn(1);larva->colCylinder.base.acFlags|=AC_HIT;EnPeehat_Larva_StateSeekPlayer(larva,gPlayState);Check(!larva->actor.update&&larvaKills==2,"Larva weapon damage follows native immediate defeat");larva=Spawn(1);larva->actor.bgCheckFlags|=BGCHECKFLAG_GROUND;EnPeehat_Larva_StateSeekPlayer(larva,gPlayState);Check(!larva->actor.update&&larvaKills==3,"Larva ground impact follows native defeat");larva=nullptr;Next(18);return;}
 if(phase==18&&frames>10){Check(kills==5&&gARPGSave.kills==5,"Five native defeats produce five ARPG kill rewards");Check(!Creatures::SpawnPeahatPractice(gPlayState,-1)&&!Creatures::SpawnPeahatPractice(gPlayState,3),"Unknown practice variants are rejected");for(int type:{0,1,2}){Actor* a=nullptr;for(int i=0;i<16&&!a;++i){GET_PLAYER(gPlayState)->actor.shape.rot.y=i*0x1000;a=Creatures::SpawnPeahatPractice(gPlayState,type);}Check(a&&a->params==type-1,"Practice chooses the correct original hunter, brood or larva actor");Actor_Kill(a);}std::vector<EnPeehat*> batch;for(int i=0;i<4;++i)batch.push_back(Spawn(i%2-1));Check(!Creatures::SpawnPeahatPractice(gPlayState,0)&&!Creatures::SpawnPeahatPractice(gPlayState,1),"Practice adult cap covers both original adult types");for(auto* a:batch)Actor_Kill(&a->actor);batch.clear();for(int i=0;i<10;++i)batch.push_back(Spawn(1));Check(!Creatures::SpawnPeahatPractice(gPlayState,2),"Practice respects the ten-larva cap");for(auto* a:batch)Actor_Kill(&a->actor);Next(19);return;}
 if(phase==19&&frames>15){Check(kills==5,"Interrupted actor removal does not fabricate defeat rewards");Warp();Next(20);return;}
 if(phase==20&&frames>100&&gPlayState&&GameInteractor::IsPlayerInControl()){Check(kills==5,"Scene teardown does not repeat Peahat rewards");if(!visual){phase=99;Write("passed");return;}Clear();fixture=nearPlayer;Camera();enemy=Spawn(-1);Next(21);return;}
 if(phase==21){Camera();if(enemy->actionFunc==EnPeehat_Ground_StateSeekPlayer&&frames>65){gPlayState->frameAdvCtx.enabled=true;phase=98;Write("passed");}}
 if(frames>1300)throw std::runtime_error("Peahat integration timeout");
 }catch(const std::exception& e){phase=99;if(gPlayState)gPlayState->frameAdvCtx.enabled=true;Write("failed",e.what());}}
void Register(){auto* enabled=std::getenv("SOH_ARPG_PEAHAT_QA");auto* home=std::getenv("SHIP_HOME");if(!enabled||std::string(enabled)!="1"||!home||!std::filesystem::path(home).filename().string().starts_with("soh-arpg-qa-"))return;output=std::filesystem::path(home)/"peahat-results.json";visual=std::getenv("SOH_ARPG_PEAHAT_UI")!=nullptr;
 GameInteractor::Instance->RegisterGameHook<GameInteractor::OnGameFrameUpdate>(Tick);
 GameInteractor::Instance->RegisterGameHook<GameInteractor::OnEnemyDefeat>([](void* p){auto* a=static_cast<Actor*>(p);if(a->id==ACTOR_EN_PEEHAT){++kills;if(a->params>0)++larvaKills;else ++adultKills;}});
 GameInteractor::Instance->RegisterGameHook<GameInteractor::OnPlayDrawEnd>([](){if(!gPlayState)return;if(enemy&&Alive(&enemy->actor)){++drawFrames;rotations.insert(enemy->bladeRot);stunFrames+=enemy->actionFunc==EnPeehat_StateBoomerangStunned;if(enemy->actor.params==-1&&enemy->actor.colChkInfo.health>0){bladeTips|=std::abs(Math_Vec3f_DistXYZ(enemy->bladeTip,enemy->bladeTip+1)-396)<.2;auto* q=enemy->colliderQuad.dim.quad;bladeQuad|=std::abs(Math_Vec3f_DistXYZ(q,q+1)-std::sqrt(2.f)*162)<.2;}}if(larva&&Alive(&larva->actor))recoilFrames+=larva->actionFunc==EnPeehat_StateAttackRecoil;for(auto* a=gPlayState->actorCtx.actorLists[ACTORCAT_EXPLOSIVE].head;a;a=a->next)if(a->id==ACTOR_EN_BOM&&a->update&&!bombs.contains(a)){bombs.insert(a);++bombCount;}});
}
static RegisterShipInitFunc init(Register);
